import{_ as r,o as a,c as t,a2 as i}from"./chunks/framework.DDk04jjR.js";const h=JSON.parse('{"title":"Про нас","description":"Віртуальна лабораторія моделювання при Самбірському фаховому коледжі","frontmatter":{"layout":"page","title":"Про нас","description":"Віртуальна лабораторія моделювання при Самбірському фаховому коледжі"},"headers":[],"relativePath":"lighting-demo.md","filePath":"lighting-demo.md"}'),o={name:"lighting-demo.md"};function d(n,e,l,s,m,g){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="🏫-про-нас" tabindex="-1">🏫 Про нас <a class="header-anchor" href="#🏫-про-нас" aria-label="Permalink to &quot;🏫 Про нас&quot;">​</a></h1><hr><h2 id="хто-ми" tabindex="-1">Хто ми <a class="header-anchor" href="#хто-ми" aria-label="Permalink to &quot;Хто ми&quot;">​</a></h2><p>Віртуальна лабораторія моделювання створена на базі <strong>Самбірського фахового коледжу економіки та інформаційних технологій</strong> (Львівська обл., м. Самбір, вул. Крушельницької, 7).</p><hr><h2 id="🎯-наша-місія" tabindex="-1">🎯 Наша місія <a class="header-anchor" href="#🎯-наша-місія" aria-label="Permalink to &quot;🎯 Наша місія&quot;">​</a></h2><p>Ми прагнемо зробити сучасні технології доступними для кожного студента та учасника клубу, відкриваючи світ 3D-моделювання та цифрового виробництва.</p><hr><h2 id="🛠️-чим-заимаємось" tabindex="-1">🛠️ Чим займаємось <a class="header-anchor" href="#🛠️-чим-заимаємось" aria-label="Permalink to &quot;🛠️ Чим займаємось&quot;">​</a></h2><div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(260px, 1fr));gap:1.5rem;margin:2rem 0;"><div style="background:linear-gradient(135deg, #eef2ff, #e8e0ff);border-radius:16px;padding:1.5rem;border:1px solid #e0e0ef;text-align:center;"><div style="font-size:2.5rem;margin-bottom:0.5rem;">🎨</div><h3 style="margin-top:0;">Blender &amp; Fusion 360</h3><p>Навчання моделюванню у Blender та Fusion 360</p></div><div style="background:linear-gradient(135deg, #eef2ff, #e8e0ff);border-radius:16px;padding:1.5rem;border:1px solid #e0e0ef;text-align:center;"><div style="font-size:2.5rem;margin-bottom:0.5rem;">🖨️</div><h3 style="margin-top:0;">3D-друк</h3><p>Ознайомлення з основами 3D-друку</p></div><div style="background:linear-gradient(135deg, #eef2ff, #e8e0ff);border-radius:16px;padding:1.5rem;border:1px solid #e0e0ef;text-align:center;"><div style="font-size:2.5rem;margin-bottom:0.5rem;">💡</div><h3 style="margin-top:0;">Цифровий дизайн</h3><p>Практичні заняття з цифрового дизайну та візуалізації</p></div><div style="background:linear-gradient(135deg, #eef2ff, #e8e0ff);border-radius:16px;padding:1.5rem;border:1px solid #e0e0ef;text-align:center;"><div style="font-size:2.5rem;margin-bottom:0.5rem;">🚀</div><h3 style="margin-top:0;">Інноваційні технології</h3><p>Підготовка до роботи з інноваційними технологіями у навчанні та професійній діяльності</p></div></div><hr><h2 id="💡-наш-підхід" tabindex="-1">💡 Наш підхід <a class="header-anchor" href="#💡-наш-підхід" aria-label="Permalink to &quot;💡 Наш підхід&quot;">​</a></h2><p>Ми поєднуємо теорію з практикою, щоб кожен міг реалізувати власні ідеї — <strong>від віртуальної моделі до готового виробу</strong>.</p><div style="background:linear-gradient(135deg, #6366f1, #8b5cf6, #a855f7);border-radius:16px;padding:2rem;margin:2rem 0;color:white;text-align:center;"><h3 style="margin-top:0;color:white;border-bottom:none;">🌟 Від ідеї — до реальності</h3><p style="color:rgba(255,255,255,0.9);font-size:1.1rem;margin-bottom:0;">Навчаємо створювати, проєктувати та втілювати в життя за допомогою сучасних 3D-технологій.</p></div><hr><h2 id="📍-контакти" tabindex="-1">📍 Контакти <a class="header-anchor" href="#📍-контакти" aria-label="Permalink to &quot;📍 Контакти&quot;">​</a></h2><p><strong>Самбірський фаховий коледж економіки та інформаційних технологій</strong></p><ul><li>📍 Львівська обл., м. Самбір, вул. Крушельницької, 7</li><li>🌐 Віртуальна лабораторія 3DLab</li><li><a href="https://www.adobe.com/products/color/basics/" target="_blank" rel="noreferrer">Color Theory in 3D</a></li></ul>',18)])])}const f=r(o,[["render",d]]);export{h as __pageData,f as default};
